const M = "";

// Dekodierer, wörtlich aus tools/map/export.mjs
/** Ebener Rahmen einer Kante: [x, y, ux, uy, kx] – Lage in km (x = Länge · kx nach Osten, y = Breite · KY nach Norden), Richtung des letzten Abschnitts als Einheitsvektor (ux, uy), zu Beginn die Sehne a → b, und kx = km je Grad Länge auf der Breite von Knoten a. */
function rahmen(la0, lo0, la1, lo1) {
  const kx = 111.32 * Math.cos(la0 * RAD);
  const x = lo0 * kx;
  const y = la0 * KY;
  const dx = lo1 * kx - x;
  const dy = la1 * KY - y;
  const l = Math.sqrt(dx * dx + dy * dy);
  return l > 0 ? [x, y, dx / l, dy / l, kx] : [x, y, 0, 1, kx];
}
/** Ein Schritt im Rahmen z: a Raster längs der letzten Richtung, c quer dazu (nach links); dreht den Rahmen mit. */
function schritt(z, a, c) {
  const sx = RASTER_KM * (a * z[2] - c * z[3]);
  const sy = RASTER_KM * (a * z[3] + c * z[2]);
  const l = Math.sqrt(sx * sx + sy * sy);
  z[0] += sx;
  z[1] += sy;
  z[2] = sx / l;
  z[3] = sy / l;
}
/** Zahl ohne Vorzeichen aus Zeichen k von s: das Zeichen trägt die Oktave und ihre zwei obersten Bits, die übrigen Bits kommen aus dem Bitstrom b ({ s, p, acc, n }). */
function symbolLesen(s, k, b) {
  let c = s.charCodeAt(k) - 35;
  if (c > 57) c--;
  if (c >= 4) {
    const m = (c >> 2) - 1;
    while (b.n < m) {
      let d = b.s.charCodeAt(b.p++) - 35;
      if (d > 57) d--;
      b.acc |= d << b.n;
      b.n += 6;
    }
    c = ((4 | (c & 3)) << m) | (b.acc & ((1 << m) - 1));
    b.acc >>>= m;
    b.n -= m;
  }
  return c;
}
/** Dekodiert eine Kante aus ihren Zeichenketten (längs, quer, Höhe, Zusatzbits) und der Lage ihrer Knoten. */
function lesen(al, ql, hl, xl, la0, lo0, la1, lo1, matched) {
  const n = ql.length + 2;
  const lat = new Float64Array(n);
  const lon = new Float64Array(n);
  const elev = new Float32Array(n);
  const b = { s: xl, p: 0, acc: 0, n: 0 };
  const z = rahmen(la0, lo0, la1, lo1);
  lat[0] = la0;
  lon[0] = lo0;
  let pa = 0;
  for (let p = 1; p < n - 1; p++) {
    let a = symbolLesen(al, pa++, b) - 1;
    if (a < 0) a = -symbolLesen(al, pa++, b);
    const c = symbolLesen(ql, p - 1, b);
    schritt(z, a, (c >>> 1) ^ -(c & 1));
    lat[p] = z[1] / KY;
    lon[p] = z[0] / z[4];
  }
  lat[n - 1] = la1;
  lon[n - 1] = lo1;
  let h = 0;
  for (let p = 0; p < n; p++) {
    const v = symbolLesen(hl, p, b);
    h += (v >>> 1) ^ -(v & 1);
    elev[p] = h;
  }
  return { n, lat, lon, elev, matched };
}

/** Anzahl der Verläufe (= Zahl der Kanten). */
export const shapeCount = Q.length;
const cache = new Array(shapeCount);

/**
 * Verlauf der Kante i: { n, lat: Float64Array, lon: Float64Array, elev: Float32Array, matched: 0 | 1 | 2 }.
 * matched sagt, wie weit die Lage einem echten Verlauf folgt; elev (ganze Meter) gilt bei jedem Wert. Wird beim
 * ersten Abruf dekodiert und zwischengespeichert: jeder Aufruf mit demselben i gibt dasselbe Objekt mit denselben
 * Feldern zurück, sie sind nur zum Lesen da.
 */
export function edgeShape(i) {
  const hit = cache[i];
  if (hit) return hit;
  if (!Number.isInteger(i) || i < 0 || i >= shapeCount) throw new RangeError(`edgeShape: keine Kante ${i} (0 … ${shapeCount - 1})`);
  const [a, b] = EDGES[i];
  const shape = lesen(A[i], Q[i], H[i], X[i], NODES[a][2], NODES[a][3], NODES[b][2], NODES[b][3], M.charCodeAt(i) - 48);
  cache[i] = shape;
  return shape;
}
